PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, google_sub TEXT NOT NULL UNIQUE, email TEXT NOT NULL, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, verifier TEXT NOT NULL, nonce TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE TABLE members (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, joined_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE INDEX members_user ON members(user_id,workspace_id);
CREATE TABLE mailboxes (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL UNIQUE REFERENCES workspaces(id) ON DELETE CASCADE, email TEXT NOT NULL, alias TEXT NOT NULL UNIQUE, verified_at INTEGER, setup_content TEXT, setup_expires_at INTEGER);
CREATE TABLE rules (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, sender TEXT NOT NULL, subject_contains TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL CHECK(mode IN ('codes','links','read')), link_host TEXT NOT NULL DEFAULT '', retention_minutes INTEGER NOT NULL DEFAULT 15 CHECK(retention_minutes BETWEEN 5 AND 1440), enabled INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE(workspace_id,sender,subject_contains));
CREATE INDEX rules_workspace ON rules(workspace_id);
CREATE TABLE grants (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, rule_id TEXT NOT NULL REFERENCES rules(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mode TEXT NOT NULL CHECK(mode IN ('blocked','codes','links','read')), expires_at INTEGER, starts_at INTEGER NOT NULL, PRIMARY KEY(rule_id,user_id));
CREATE TABLE invitations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, accepted_at INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX invitations_workspace ON invitations(workspace_id,created_at);
CREATE TABLE messages (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, rule_id TEXT NOT NULL REFERENCES rules(id) ON DELETE CASCADE, content TEXT NOT NULL, received_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, dedupe TEXT NOT NULL, UNIQUE(rule_id,dedupe));
CREATE INDEX messages_workspace_expiry ON messages(workspace_id,expires_at,received_at);
CREATE TABLE events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, actor_id TEXT, action TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX events_workspace ON events(workspace_id,created_at);
CREATE TABLE rate_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
